#!/bin/bash
# Nightly backup for ${PROJECT}: pg_dump (custom format) + filestore tar into
# ${BACKUP_DIR}, keeping ${BACKUP_KEEP_DAYS} days. Run as root by ${SERVICE}-backup.timer.
# Only the nightly files are pruned; manual dumps named *_before_* are kept.
# Generated by baremetal/install.sh.
set -euo pipefail
DB=${DB_NAME}
DEST=${BACKUP_DIR}
STAMP=$(date +%F_%H%M)
umask 077
mkdir -p "$DEST"
runuser -u postgres -- pg_dump -p ${PG_PORT} -Fc -Z 6 "$DB" > "$DEST/${DB}_${STAMP}.dump.part"
mv "$DEST/${DB}_${STAMP}.dump.part" "$DEST/${DB}_${STAMP}.dump"
tar -C ${DATA_DIR}/filestore -czf "$DEST/${DB}_filestore_${STAMP}.tgz" "$DB" || echo "WARNING: filestore archive failed" >&2
find "$DEST" -maxdepth 1 -type f \( -name "${DB}_[0-9]*.dump" -o -name "${DB}_filestore_[0-9]*.tgz" -o -name "*.part" \) -mtime +${BACKUP_KEEP_DAYS} -delete
echo "backup done: $DEST/${DB}_${STAMP}.dump"
